#!/usr/bin/env python3
"""Build-time generator for the JS Unicode tables.

Implements the RFC 5892 derivation algorithm over the host Unicode database
(the same Unicode 15.0 repertoire the reference binary's bidi/NFC checks use)
and emits compact range tables consumed by /output/lib/unicode/*.mjs.

Only public standard data is used here (general categories, case folding,
NFKC, bidi classes).  Nothing from the idna package is read.
"""
import sys
import unicodedata

MAX = 0x10FFFF

# ---------------------------------------------------------------- RFC 5892 F.
EXCEPTIONS = {}
for cp in (0x00DF, 0x03C2, 0x06FD, 0x06FE, 0x0F0B, 0x3007):
    EXCEPTIONS[cp] = 'PVALID'
for cp in (0x00B7, 0x0375, 0x05F3, 0x05F4, 0x30FB):
    EXCEPTIONS[cp] = 'CONTEXTO'
for cp in list(range(0x0660, 0x066A)) + list(range(0x06F0, 0x06FA)):
    EXCEPTIONS[cp] = 'CONTEXTO'
for cp in (0x0640, 0x07FA, 0x302E, 0x302F, 0x303B) + tuple(range(0x3031, 0x3036)):
    EXCEPTIONS[cp] = 'DISALLOWED'

WHITE_SPACE = set(range(0x09, 0x0E)) | {0x20, 0x85, 0xA0, 0x1680, 0x2028,
                                        0x2029, 0x202F, 0x205F, 0x3000} \
              | set(range(0x2000, 0x200B))

DEFAULT_IGNORABLE = set()
for a, b in [(0x00AD, 0x00AD), (0x034F, 0x034F), (0x061C, 0x061C),
             (0x115F, 0x1160), (0x17B4, 0x17B5), (0x180B, 0x180F),
             (0x200B, 0x200F), (0x202A, 0x202E), (0x2060, 0x206F),
             (0x3164, 0x3164), (0xFE00, 0xFE0F), (0xFEFF, 0xFEFF),
             (0xFFA0, 0xFFA0), (0xFFF0, 0xFFF8), (0x1BCA0, 0x1BCA3),
             (0x1D173, 0x1D17A), (0xE0000, 0xE0FFF)]:
    DEFAULT_IGNORABLE.update(range(a, b + 1))

IGNORABLE_BLOCKS = set(range(0x20D0, 0x2100)) | set(range(0x1D100, 0x1D200)) \
                   | set(range(0x1D200, 0x1D250))

OLD_HANGUL_JAMO = set(range(0x1100, 0x1200)) | set(range(0xA960, 0xA97D)) \
                  | set(range(0xD7B0, 0xD7C7)) | set(range(0xD7CB, 0xD7FC))

LETTER_DIGITS = {'Ll', 'Lu', 'Lo', 'Lm', 'Mn', 'Mc', 'Nd'}


def is_noncharacter(cp):
    return (0xFDD0 <= cp <= 0xFDEF) or (cp & 0xFFFE) == 0xFFFE


def nfkc(s):
    return unicodedata.normalize('NFKC', s)


def derive(cp):
    if cp in EXCEPTIONS:
        return EXCEPTIONS[cp]
    if 0xD800 <= cp <= 0xDFFF:
        return 'DISALLOWED'
    cat = unicodedata.category(chr(cp))
    if cat == 'Cn' and not is_noncharacter(cp):
        return 'UNASSIGNED'
    if cp == 0x2D or 0x30 <= cp <= 0x39 or 0x61 <= cp <= 0x7A:
        return 'PVALID'
    if cp in (0x200C, 0x200D):
        return 'CONTEXTJ'
    c = chr(cp)
    if c != nfkc(nfkc(c).casefold()):
        return 'DISALLOWED'
    if cp in DEFAULT_IGNORABLE or cp in WHITE_SPACE or is_noncharacter(cp):
        return 'DISALLOWED'
    if cp in IGNORABLE_BLOCKS:
        return 'DISALLOWED'
    if cp in OLD_HANGUL_JAMO:
        return 'DISALLOWED'
    if cat in LETTER_DIGITS:
        return 'PVALID'
    return 'DISALLOWED'


def to_ranges(cps):
    out = []
    for cp in sorted(cps):
        if out and out[-1][1] == cp - 1:
            out[-1][1] = cp
        else:
            out.append([cp, cp])
    return out


def fmt(ranges):
    parts = []
    for a, b in ranges:
        parts.append('%x' % a if a == b else '%x+%x' % (a, b - a))
    return ','.join(parts)


def main():
    classes = {'PVALID': [], 'CONTEXTJ': [], 'CONTEXTO': []}
    bidi = {}
    mark = []
    virama = []
    for cp in range(MAX + 1):
        cls = derive(cp)
        if cls in classes:
            classes[cls].append(cp)
        if 0xD800 <= cp <= 0xDFFF:
            continue
        c = chr(cp)
        b = unicodedata.bidirectional(c)
        if b:
            bidi.setdefault(b, []).append(cp)
        cat = unicodedata.category(c)
        if cat[0] == 'M':
            mark.append(cp)
        if unicodedata.combining(c) == 9:
            virama.append(cp)

    with open(sys.argv[1], 'w') as f:
        f.write('// Generated by gen/gen_tables.py -- do not edit by hand.\n')
        f.write('// RFC 5892 derived property values and the Unicode character\n')
        f.write('// properties needed by RFC 5891/5893 label validation.\n\n')
        for name in ('PVALID', 'CONTEXTJ', 'CONTEXTO'):
            f.write('export const %s = %r;\n\n' % (name, fmt(to_ranges(classes[name]))))
        f.write('export const CATEGORY_MARK = %r;\n\n' % fmt(to_ranges(mark)))
        f.write('export const VIRAMA = %r;\n\n' % fmt(to_ranges(virama)))
        f.write('export const BIDI_CLASSES = {\n')
        for name in sorted(bidi):
            f.write('  %s: %r,\n' % (name, fmt(to_ranges(bidi[name]))))
        f.write('};\n')

    sys.stderr.write('PVALID ranges: %d\n' % len(to_ranges(classes['PVALID'])))
    sys.stderr.write('CONTEXTO: %s\n' % fmt(to_ranges(classes['CONTEXTO'])))
    sys.stderr.write('CONTEXTJ: %s\n' % fmt(to_ranges(classes['CONTEXTJ'])))
    sys.stderr.write('VIRAMA: %s\n' % fmt(to_ranges(virama)))


main()

