// Build-time generator for lib/unicode/scripts.mjs.
// RFC 5892 Appendix A only needs five scripts (Greek, Hebrew, Hiragana,
// Katakana, Han) for its CONTEXTO rules, so only those are emitted.
import { writeFileSync } from 'node:fs';

const SCRIPTS = ['Greek', 'Hebrew', 'Hiragana', 'Katakana', 'Han'];

// Assigned after the Unicode version bundled with this Node build; kept as an
// explicit patch list so the tables stay aligned with the reference data.
const EXTRA = {
  Han: [[0x31350, 0x323AF]], // CJK Unified Ideographs Extension H
};

function fmt(ranges) {
  return ranges
    .map(([a, b]) => (a === b ? a.toString(16) : `${a.toString(16)}+${(b - a).toString(16)}`))
    .join(',');
}

function rangesFor(script) {
  const re = new RegExp(`\\p{Script=${script}}`, 'u');
  const out = [];
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    if (cp >= 0xd800 && cp <= 0xdfff) continue;
    if (!re.test(String.fromCodePoint(cp))) continue;
    const last = out[out.length - 1];
    if (last && last[1] === cp - 1) last[1] = cp;
    else out.push([cp, cp]);
  }
  for (const [a, b] of EXTRA[script] ?? []) {
    const last = out[out.length - 1];
    if (last && last[1] === a - 1) last[1] = b;
    else out.push([a, b]);
  }
  return out;
}

let src = '// Generated by gen/gen_scripts.mjs -- do not edit by hand.\n';
src += '// Unicode Script property ranges for the scripts named by RFC 5892\n';
src += '// Appendix A (CONTEXTO rules).\n\n';
src += 'export const SCRIPTS = {\n';
for (const script of SCRIPTS) src += `  ${script}: '${fmt(rangesFor(script))}',\n`;
src += '};\n';
writeFileSync(process.argv[2], src);

