// Compact range-set decoding and membership tests.
//
// A spec is a comma separated list of hex entries, each either a single
// codepoint ("df") or a start plus a length delta ("61+19" == U+0061..U+007A).
// Specs are decoded lazily on first use so that pulling in a table costs
// nothing until something actually queries it.

/**
 * Decode a range spec into a flat [start0, end0, start1, end1, ...] array.
 * @param {string} spec
 * @returns {Int32Array}
 */
export function decodeRanges(spec) {
  if (!spec) return new Int32Array(0);
  const entries = spec.split(',');
  const ranges = new Int32Array(entries.length * 2);
  let i = 0;
  for (const entry of entries) {
    const plus = entry.indexOf('+');
    if (plus < 0) {
      const cp = parseInt(entry, 16);
      ranges[i++] = cp;
      ranges[i++] = cp;
    } else {
      const start = parseInt(entry.slice(0, plus), 16);
      ranges[i++] = start;
      ranges[i++] = start + parseInt(entry.slice(plus + 1), 16);
    }
  }
  return ranges;
}

/**
 * Binary search a flat range array for `cp`.
 * @param {Int32Array} ranges
 * @param {number} cp
 * @returns {boolean}
 */
export function rangesContain(ranges, cp) {
  let lo = 0;
  let hi = ranges.length / 2 - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < ranges[mid * 2]) hi = mid - 1;
    else if (cp > ranges[mid * 2 + 1]) lo = mid + 1;
    else return true;
  }
  return false;
}

class RangeSet {
  #spec;
  #ranges = null;

  constructor(spec) {
    this.#spec = spec;
  }

  has(cp) {
    if (this.#ranges === null) this.#ranges = decodeRanges(this.#spec);
    return rangesContain(this.#ranges, cp);
  }
}

/**
 * Build a lazily decoded set from a range spec.
 * @param {string} spec
 * @returns {RangeSet}
 */
export function rangeSet(spec) {
  return new RangeSet(spec);
}

