// Character property accessors used by the IDNA validation rules.
//
// Every table is a range spec from ./tables.mjs (RFC 5892 derived properties
// plus the plain Unicode properties the checks need), ./scripts.mjs or
// ./joining.mjs.

import {
  BIDI_CLASSES,
  CATEGORY_MARK,
  CONTEXTJ,
  CONTEXTO,
  PVALID,
  UNPRINTABLE,
  VIRAMA,
} from './tables.mjs';
import { SCRIPTS } from './scripts.mjs';
import { JOINING_TYPES } from './joining.mjs';
import { decodeRanges, rangeSet, rangesContain } from './rangeset.mjs';

/** RFC 5892 derived property values. */
export const PROPERTY_PVALID = 'PVALID';
export const PROPERTY_CONTEXTJ = 'CONTEXTJ';
export const PROPERTY_CONTEXTO = 'CONTEXTO';
export const PROPERTY_DISALLOWED = 'DISALLOWED';

const pvalid = rangeSet(PVALID);
const contextj = rangeSet(CONTEXTJ);
const contexto = rangeSet(CONTEXTO);
const marks = rangeSet(CATEGORY_MARK);
const viramas = rangeSet(VIRAMA);
const unprintable = rangeSet(UNPRINTABLE);

const scriptSets = new Map();
const joiningSets = new Map();

/**
 * RFC 5892 derived property of a codepoint. Unassigned codepoints and
 * everything not explicitly permitted come back as DISALLOWED.
 * @param {number} cp
 * @returns {string}
 */
export function idnaProperty(cp) {
  if (pvalid.has(cp)) return PROPERTY_PVALID;
  if (contextj.has(cp)) return PROPERTY_CONTEXTJ;
  if (contexto.has(cp)) return PROPERTY_CONTEXTO;
  return PROPERTY_DISALLOWED;
}

/**
 * True when the codepoint's general category is Mn, Mc or Me.
 * @param {number} cp
 */
export function isCombiningMark(cp) {
  return marks.has(cp);
}

/**
 * True when the codepoint has canonical combining class 9 (Virama).
 * @param {number} cp
 */
export function isVirama(cp) {
  return viramas.has(cp);
}

/**
 * True when `str.isprintable()` would be false in Python, i.e. when repr()
 * renders the character as an escape sequence.
 * @param {number} cp
 */
export function isUnprintable(cp) {
  return unprintable.has(cp);
}

/**
 * True when the codepoint's Script property is `name`.
 * @param {number} cp
 * @param {string} name
 */
export function isScript(cp, name) {
  let set = scriptSets.get(name);
  if (set === undefined) {
    set = rangeSet(SCRIPTS[name] ?? '');
    scriptSets.set(name, set);
  }
  return set.has(cp);
}

/**
 * Joining_Type of a codepoint: 'L', 'R', 'D', 'C', 'T' or 'U' (the default).
 * @param {number} cp
 * @returns {string}
 */
export function joiningType(cp) {
  for (const type of Object.keys(JOINING_TYPES)) {
    let set = joiningSets.get(type);
    if (set === undefined) {
      set = rangeSet(JOINING_TYPES[type]);
      joiningSets.set(type, set);
    }
    if (set.has(cp)) return type;
  }
  return 'U';
}

let bidiRanges = null;
let bidiNames = null;

function buildBidiIndex() {
  const collected = [];
  bidiNames = Object.keys(BIDI_CLASSES);
  for (let i = 0; i < bidiNames.length; i++) {
    const ranges = decodeRanges(BIDI_CLASSES[bidiNames[i]]);
    for (let j = 0; j < ranges.length; j += 2) {
      collected.push([ranges[j], ranges[j + 1], i]);
    }
  }
  collected.sort((a, b) => a[0] - b[0]);
  bidiRanges = new Int32Array(collected.length * 3);
  for (let i = 0; i < collected.length; i++) {
    bidiRanges[i * 3] = collected[i][0];
    bidiRanges[i * 3 + 1] = collected[i][1];
    bidiRanges[i * 3 + 2] = collected[i][2];
  }
}

/**
 * Bidi_Class of a codepoint, or '' for codepoints the character database does
 * not assign one to (unassigned codepoints).
 * @param {number} cp
 * @returns {string}
 */
export function bidiClass(cp) {
  if (bidiRanges === null) buildBidiIndex();
  let lo = 0;
  let hi = bidiRanges.length / 3 - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < bidiRanges[mid * 3]) hi = mid - 1;
    else if (cp > bidiRanges[mid * 3 + 1]) lo = mid + 1;
    else return bidiNames[bidiRanges[mid * 3 + 2]];
  }
  return '';
}

export { rangesContain };

