// Build-time generator for lib/unicode/joining.mjs.
//
// Joining_Type is not exposed by any Node built-in, so the L/R/D sets are
// recovered from the reference CLI's own behaviour: RFC 5892 rule A.1 accepts
// ZWNJ only between a {L,D} character (skipping transparent ones) and a {R,D}
// character, which makes two probes per candidate enough to classify it.
//
// Transparent (T) characters are the Mn/Me/Cf ones, per the default rule in
// ArabicShaping.txt, and are taken straight from the general category table.
import { execFile } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { bidiClass, idnaProperty } from '/output/lib/unicode/properties.mjs';

const EXE = '/workspace/dataset/test1_executable';
const CONCURRENCY = 24;
const ZWNJ = '‌';
const ARABIC_BEH = 'ب'; // Joining_Type D, Bidi_Class AL
const MONGOLIAN_A = 'ᠠ'; // Joining_Type D, Bidi_Class L

function candidates() {
  const rtl = [];
  const ltr = [];
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    if (idnaProperty(cp) !== 'PVALID') continue;
    const bc = bidiClass(cp);
    if (bc === 'R' || bc === 'AL') rtl.push(cp);
    else if ((cp >= 0x1800 && cp <= 0x18af) || (cp >= 0xa840 && cp <= 0xa877)) ltr.push(cp);
  }
  return { rtl, ltr };
}

function run(domain) {
  return new Promise((resolve) => {
    execFile(EXE, ['--domain', domain], (error) => resolve(!error));
  });
}

async function pool(jobs) {
  const results = new Array(jobs.length);
  let next = 0;
  const workers = Array.from({ length: CONCURRENCY }, async () => {
    for (;;) {
      const i = next++;
      if (i >= jobs.length) return;
      results[i] = await run(jobs[i]);
    }
  });
