const { rtl, ltr } = candidates();
const all = [...rtl, ...ltr];
const partner = (cp) => (rtl.includes(cp) ? ARABIC_BEH : MONGOLIAN_A);
process.stderr.write(`probing ${all.length} candidates (${all.length * 2} runs)\n`);

