src += '// Appendix A.1. Codepoints in none of these sets are Joining_Type U.\n\n';
src += 'export const JOINING_TYPES = {\n';
src += `  L: '${fmt(sets.L)}',\n`;
src += `  R: '${fmt(sets.R)}',\n`;
src += `  D: '${fmt(sets.D)}',\n`;
src += "  C: '200d',\n";
src += `  T: '${fmt(transparent)}',\n`;
src += '};\n';
writeFileSync(process.argv[2], src);
process.stderr.write(`L=${sets.L.length} R=${sets.R.length} D=${sets.D.length} T=${transparent.length}\n`);

