// Python's `bytes` in the small dose this port needs.
//
// idna.encode() hands back a bytes object and idna.ulabel()/alabel() behave
// differently for bytes and str inputs, so the distinction has to survive the
// port. Every byte string produced here is ASCII, so the payload is kept as a
// JS string of code units 0..255.

import { reprBytes } from './repr.mjs';

export class PyBytes {
  /** @param {string} text one character per byte */
  constructor(text) {
    this.text = text;
  }

  get length() {
    return this.text.length;
  }

  /** bytes.lower(), which only maps ASCII A-Z. */
  lower() {
    return new PyBytes(this.text.replace(/[A-Z]/g, (c) => c.toLowerCase()));
  }

  startsWith(prefix) {
    return this.text.startsWith(prefix);
  }

  slice(start, end) {
    return new PyBytes(this.text.slice(start, end));
  }

  /** bytes.decode('ascii'), which this port only ever needs for ASCII data. */
  decodeAscii() {
    return this.text;
  }

  /** b'sep'.join(parts) */
  static join(separator, parts) {
    return new PyBytes(parts.map((part) => part.text).join(separator));
  }

  /** Python renders bytes through repr() when printing them. */
  toString() {
    return reprBytes(this.text);
  }
}

/**
 * True when every character of `text` is in the ASCII range, i.e. when
 * text.encode('ascii') would succeed.
 * @param {string} text
 */
export function isAscii(text) {
  for (let i = 0; i < text.length; i++) {
    if (text.charCodeAt(i) > 0x7f) return false;
  }
  return true;
}

