// Python's repr() for str and bytes, which the reference program's output and
// error messages are built from.

import { isUnprintable } from '../unicode/properties.mjs';

const SHORT_ESCAPES = new Map([
  [0x5c, '\\\\'],
  [0x09, '\\t'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
]);

function hex(cp, width) {
  return cp.toString(16).padStart(width, '0');
}

/** Python picks double quotes only when the value contains ' but no ". */
function quoteFor(text) {
  return text.includes("'") && !text.includes('"') ? '"' : "'";
}

/**
 * repr() of a str.
 * @param {string} value
 * @returns {string}
 */
export function reprStr(value) {
  const quote = quoteFor(value);
  let out = quote;
  for (const char of value) {
    const cp = char.codePointAt(0);
    const short = SHORT_ESCAPES.get(cp);
    if (short !== undefined) out += short;
    else if (char === quote) out += `\\${char}`;
    else if (!isUnprintable(cp)) out += char;
    else if (cp < 0x100) out += `\\x${hex(cp, 2)}`;
    else if (cp < 0x10000) out += `\\u${hex(cp, 4)}`;
    else out += `\\U${hex(cp, 8)}`;
  }
  return out + quote;
}

/**
 * repr() of a bytes object held as one character per byte.
 * @param {string} text
 * @returns {string}
 */
export function reprBytes(text) {
  const quote = quoteFor(text);
  let out = `b${quote}`;
  for (const char of text) {
    const byte = char.charCodeAt(0);
    const short = SHORT_ESCAPES.get(byte);
    if (short !== undefined) out += short;
    else if (char === quote) out += `\\${char}`;
    else if (byte >= 0x20 && byte < 0x7f) out += char;
    else out += `\\x${hex(byte, 2)}`;
  }
  return out + quote;
}

/**
 * idna's U+XXXX rendering of a codepoint.
 * @param {number} cp
 */
export function unot(cp) {
  return `U+${cp.toString(16).toUpperCase().padStart(4, '0')}`;
}

