// print() and the interpreter's "unhandled exception" behaviour.

/**
 * print(value) -- str() of the value followed by a newline on stdout.
 * @param {unknown} value
 */
export function print(value) {
  process.stdout.write(`${String(value)}\n`);
}

/**
 * Report an uncaught exception the way CPython does on its last line and exit
 * with status 1. The reference implementation also prints the interpreter
 * frames of the traceback above it, which have no counterpart here.
 * @param {Error} error
 * @returns {never}
 */
export function die(error) {
  process.stderr.write(`${error.name}: ${error.message}\n`);
  process.exit(1);
}

