// The exception hierarchy of idna.core, plus the UnicodeError that Python's
// punycode codec raises. `name` carries the fully qualified Python class name
// because that is what appears on the last line of a traceback.

export class IDNAError extends Error {
  constructor(message) {
    super(message);
    this.name = 'idna.core.IDNAError';
  }
}

export class IDNABidiError extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'idna.core.IDNABidiError';
  }
}

export class InvalidCodepoint extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'idna.core.InvalidCodepoint';
  }
}

export class InvalidCodepointContext extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'idna.core.InvalidCodepointContext';
  }
}

/** Raised by the punycode codec; idna translates it into an IDNAError. */
export class UnicodeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'UnicodeError';
  }
}

